        const fieldCount = def.fields.length;
        const allConfigured = def.fields.every((f) => {
          const val = s15[`adapter_${def.id}_${f.key}`];
          return val && String(val).length > 0;
        });
        const testResult = this._adapterTestResults[def.id];
        let statusLabel;
